namespace OpenNspw;

// NSPW 1.22's scenario setups (scenario_1 to scenario_306), lifted from its machine code: the units, planes and fleets
// each places, the globals it sets, the random choices of its start, and its map, in 1.22's order, so that rand() is
// drawn as 1.22 draws it. 1.22's gas is an int, so it is read truncated. Each is tested against the emulated original
// (ScenarioSetupTests).
public partial class Nspw
{
