		var r3 = rand();
		var n5 = r3 % 4000;
		var d2 = (double)(1600 - n5);
		p1 = d2;
		p2 = -2200.0;
		L42AB92:
		var u3 = AddUnit(Side.Japan, UnitKind.Carrier, p2, p1, 135.0);
		ComputerFleets[1].Flagship = (short)u3;
